  "slots": [
    {
      "slot": 1,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 5,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "플라스틱은 ‘성형할 수 있는, 거푸집으로 조형이 가능한’이라는 의미의 ‘플라스티코스’라는 그리스어에서 온 말로, 열과 압력으로 성형할 수 있는 고분자 화합물을 이른다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "탄소 원자는 가장 바깥 전자 껍질에 4개의 전자를 갖고 있어, 다른 원자들과 전자를 공유하여 안정해질 수 있으며 다양한 형태의 공유 결합이 가능하여 거대한 분자의 골격을 이룰 수 있다.",
            "다양한 형태의 공유 결합이 가능하여",
            "거대한 분자의 골격을 이룰 수 있다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "TRUE",
          "basis": [
            "두 원자가 각각 전자를 하나씩 내어놓아 그 두 개의 전자를 한 쌍으로 공유하면 단일 결합이라 하고, 두 쌍을 공유하면 이중 결합이라 한다.",
            "공유 전자쌍이 많을수록 원자 간의 결합력은 강하다.",
            "한 쌍으로 공유하면 단일 결합",
            "두 쌍을 공유하면 이중 결합"
          ],
          "twist": null
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "에틸렌은 두 개의 탄소 원자와 네 개의 수소 원자로 이루어지는데, 두 개의 탄소 원자가 서로 이중 결합을 하고 각각의 탄소 원자는 두 개의 수소 원자와 단일 결합을 한다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": [
            "플라스틱에서 결정 영역이 차지하는 부분의 비율은 여러 조건에 따라 조절이 가능하고 물성에 영향을 미친다.",
            "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
            "결정 영역이 많아질수록",
            "화학 물질에 대한 민감성이 감소하며"
          ],
          "twist": {
            "label": "변화 방향 반전",
            "targetQuote": "화학 물질에 대한 민감성이 감소하며",
            "change": "결정 영역의 비율이 높아지는 조건은 유지하되, 그에 따라 화학 물질에 대한 민감성이 감소한다는 관계를 증가한다는 관계로 바꾼다."
          }
        }
      ]
    },
    {
      "slot": 2,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "CONCEPT",
      "concept": "에틸렌의 중합",
      "answer": 3,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "에틸렌의 중합에는 여러 가지 방법이 있는데 그중에 하나는 과산화물 개시제를 사용하는 것이다.",
            "열을 흡수한 과산화물 개시제는 가장 바깥 껍질에 7개의 전자가 있는 불안정한 상태의 원자를 가진 분자로 분해된다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "이 불안정한 원자는 안정해지기 위해 에틸렌이 가진 탄소의 이중 결합 중 더 약한 결합을 끊어 버리면서 에틸렌의 한쪽 탄소 원자와 전자를 공유하며 단일 결합 한다.",
            "이 불안정한 원자는 안정해지기 위해",
            "에틸렌이 가진 탄소의 이중 결합 중 더 약한 결합을 끊어 버리면서",
            "에틸렌의 한쪽 탄소 원자와 전자를 공유하며 단일 결합 한다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "이 불안정한 원자는 안정해지기 위해 에틸렌이 가진 탄소의 이중 결합 중 더 약한 결합을 끊어 버리면서 에틸렌의 한쪽 탄소 원자와 전자를 공유하며 단일 결합 한다.",
            "그러면 다른 쪽 탄소 원자는 공유되지 못한, 홀로 남은 전자를 갖게 된다."
          ],
          "twist": {
            "label": "전자 보유 위치 교체",
            "targetQuote": "그러면 다른 쪽 탄소 원자는 공유되지 못한, 홀로 남은 전자를 갖게 된다.",
            "change": "개시제에서 나온 불안정한 원자와 결합한 뒤 홀로 남은 전자를 갖는 탄소 원자를 다른 쪽 탄소 원자에서 그 불안정한 원자와 직접 결합한 쪽 탄소 원자로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "이 불안정한 탄소 원자는 같은 방식으로 다른 에틸렌 분자와 반응을 하게 되고, 이와 같은 반응이 이어지며 불안정해지는 탄소 원자가 계속 생성된다.",
            "에틸렌 분자들이 결합하여 더해지면 이것들은 사슬 형태를 이루며, 이 사슬은 지속적으로 성장하고 사슬 끝에는 불안정한 탄소 원자가 존재하게 된다.",
            "에틸렌 분자들이 결합하여 더해지면",
            "이 사슬은 지속적으로 성장하고 사슬 끝에는 불안정한 탄소 원자가 존재하게 된다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": [
            "성장하는 두 사슬의 끝이 서로 만나 결합하여 안정한 상태가 되면 반복적인 반응이 멈추게 된다.",
            "성장하는 두 사슬의 끝이 서로 만나 결합하여 안정한 상태가 되면",
            "반복적인 반응이 멈추게 된다."
          ],
          "twist": null
        }
      ]
    }
  ]
}

